excels.excel:

EXPORT WITH SHEET="库存库龄分析表", HEADER=true,
    MAPPING={"a":"库龄区间","b":"物料种类数","c":"库存金额","d":"金额占比","e":"风险等级"},
    FORMAT={"b":"0","c":"#,##0.00","d":"0.00%"},
    FORMULAS={
        D2:'C2/C6',D3:'C3/C6',D4:'C4/C6',D5:'C5/C6',
        B6:'SUM(B2:B5)',C6:'SUM(C2:C5)',D6:'SUM(D2:D5)'
    },
    STYLE={
        ROW 6:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        C5:{color:red,bold:true},
        D5:{color:red,bold:true}
    }
